fn page_limit(raw: Option<&str>) -> Result<usize, &'static str> {
let Some(text)=raw else{return Ok(20);};
if text.is_empty()||text.len()>3||!text.as_bytes().iter().all(u8::is_ascii_digit){return Err("limit");}
let n:usize=text.parse().map_err(|_|"limit")?;
if (1..=100).contains(&n){Ok(n)}else{Err("limit")}
}

