fn form_value(raw: &str) -> Result<String, &'static str> {
fn digit(c:u8)->Option<u8>{match c{b'0'..=b'9'=>Some(c-b'0'),b'a'..=b'f'=>Some(c-b'a'+10),b'A'..=b'F'=>Some(c-b'A'+10),_=>None}}
let bytes=raw.as_bytes();let mut out=Vec::new();let mut i=0;
while i<bytes.len(){match bytes[i]{b'+'=>out.push(b' '),b'%'=>{if i+2>=bytes.len(){return Err("percent");}let hi=digit(bytes[i+1]).ok_or("percent")?;let lo=digit(bytes[i+2]).ok_or("percent")?;out.push(hi*16+lo);i+=2;},b=>out.push(b)}i+=1;}
String::from_utf8(out).map_err(|_|"utf8")
}

