fn json_string(s: &str) -> String {
let mut out=String::from("\"");
for c in s.chars(){match c{'"'=>out.push_str("\\\""),'\\'=>out.push_str("\\\\"),c if (c as u32)<32=>out.push_str(&format!("\\u{:04x}",c as u32)),c=>out.push(c)}}
out.push('"');out
}

