#[derive(Debug,PartialEq)] struct Book{version:u32,title:String}
fn update_title(rows: &mut std::collections::HashMap<u32,Book>, id: u32, expected: u32, title: &str) -> u16 {
if title.trim().is_empty(){return 400;}
let Some(book)=rows.get_mut(&id)else{return 404;};
if book.version!=expected{return 409;}
let Some(next)=book.version.checked_add(1)else{return 409;};
book.title=title.to_owned();book.version=next;200
}
